def decode_snd(file_bytes):
    tree_size_bytes = u16le(file_bytes[0:2])
    rate_word       = u16le(file_bytes[2:4])  # 0xFFFF = default, else PIT divisor
    if tree_size_bytes == 0:
        return file_bytes[4:]  # raw 8-bit PCM
    tree = struct.unpack(f'<{tree_size_bytes//2}h', file_bytes[4:4+tree_size_bytes])
    bitstream = file_bytes[4+tree_size_bytes:]
    samples = []
    node = 0
    for bit in iter_bits_msb_first(bitstream):
        child = tree[node*2 + bit]
        if child >= 0:
            samples.append(child & 0xFF)  # 8-bit sample
            node = 0
        else:
            node = -child
    return samples  # ready to play at sample rate from header (or default)
